from __future__ import annotations
import argparse,pathlib,datetime,collections,decimal,time
from common import save,load,db,query,csvwrite
def run(package,stage,investigation=None):
    package=pathlib.Path(package).resolve();c=db(package);started=time.perf_counter()
    def export(name,sql,params=(),folder='cutoff'):
        (package/'sql/local').mkdir(parents=True,exist_ok=True);(package/'sql/local'/f'{name}.sql').write_text(sql,encoding='utf-8');cols,rows=query(c,sql,params);csvwrite(package/'evidence'/folder/f'{name}.csv',cols,rows);return cols,rows
    if stage=='p1':
        export('daily_full',"""SELECT cal.Date,cal.Month,COUNT(DISTINCT o.OrderID) OrdersCreated,COUNT(DISTINCT CASE WHEN l.UnpickedUnits>0 THEN o.OrderID END) UnpickedOrders,COUNT(CASE WHEN l.UnpickedUnits>0 THEN l.OrderLineID END) UnpickedLines,COALESCE(SUM(l.UnpickedUnits),0)::BIGINT UnpickedUnits,COALESCE(SUM(l.Quantity),0)::BIGINT OrderedUnits FROM analytics.calendar cal LEFT JOIN analytics.orders o ON o.OrderDate=cal.Date AND o.ScenarioID='base' LEFT JOIN analytics.order_lines l ON l.OrderID=o.OrderID AND l.ScenarioID='base' WHERE cal.Date<=DATE '2016-05-31' GROUP BY cal.Date,cal.Month ORDER BY cal.Date""")
        cols,daily=query(c,"SELECT * FROM read_csv(?,header=true)",[str(package/'evidence/cutoff/daily_full.csv')])
        csvwrite(package/'evidence/cutoff/daily_may.csv',cols,[r for r in daily if str(r[0])[:7]=='2016-05'])
        csvwrite(package/'evidence/cutoff/daily_april.csv',cols,[r for r in daily if str(r[0])[:7]=='2016-04'])
        export('monthly_full',"""SELECT strftime(o.OrderDate,'%Y-%m') AS Month,COUNT(DISTINCT o.OrderID) OrdersCreated,COUNT(DISTINCT CASE WHEN l.UnpickedUnits>0 THEN o.OrderID END) UnpickedOrders,COUNT(CASE WHEN l.UnpickedUnits>0 THEN l.OrderLineID END) UnpickedLines,SUM(l.UnpickedUnits)::BIGINT UnpickedUnits FROM analytics.orders o JOIN analytics.order_lines l ON l.OrderID=o.OrderID AND l.ScenarioID=o.ScenarioID WHERE o.ScenarioID='base' GROUP BY 1 ORDER BY 1""")
        export('target_concentration',"""SELECT EXISTS(SELECT 1 FROM raw.Sales_Orders orig WHERE orig.BackorderOrderID=o.OrderID) IsBackorderTarget,COUNT(DISTINCT o.OrderID) Orders,COUNT(*) Lines,SUM(l.UnpickedUnits)::BIGINT Units FROM analytics.orders o JOIN analytics.order_lines l ON l.OrderID=o.OrderID AND l.ScenarioID=o.ScenarioID WHERE o.ScenarioID='base' AND l.UnpickedUnits>0 GROUP BY 1 ORDER BY 1""")
        export('age_buckets',"""SELECT CASE WHEN date_diff('day',OrderDate,DATE '2016-05-31')=0 THEN '0 days' WHEN date_diff('day',OrderDate,DATE '2016-05-31')<=7 THEN '1-7 days' WHEN date_diff('day',OrderDate,DATE '2016-05-31')<=30 THEN '8-30 days' WHEN date_diff('day',OrderDate,DATE '2016-05-31')<=90 THEN '31-90 days' ELSE '91+ days' END AgeBucket,COUNT(DISTINCT OrderID) Orders,COUNT(*) Lines,SUM(UnpickedUnits)::BIGINT Units FROM analytics.order_lines WHERE ScenarioID='base' AND UnpickedUnits>0 GROUP BY 1 ORDER BY MIN(OrderDate) DESC""")
        export('item_concentration',"""SELECT l.StockItemID,s.StockItemName,COUNT(DISTINCT l.OrderID) Orders,COUNT(*) Lines,SUM(l.UnpickedUnits)::BIGINT Units FROM analytics.order_lines l JOIN raw.Warehouse_StockItems s USING(StockItemID) WHERE l.ScenarioID='base' AND l.UnpickedUnits>0 GROUP BY 1,2 ORDER BY Units DESC,l.StockItemID""")
        export('underpicked_dates',"SELECT MIN(OrderDate) FirstDate,MAX(OrderDate) LastDate,COUNT(DISTINCT OrderID) Orders,COUNT(*) Lines,SUM(UnpickedUnits)::BIGINT Units FROM analytics.order_lines WHERE ScenarioID='base' AND UnpickedUnits>0")
        totals=c.execute("SELECT COUNT(DISTINCT OrderID),SUM(UnpickedUnits) FROM analytics.order_lines WHERE ScenarioID='base' AND UnpickedUnits>0").fetchone();windows=[]
        for n in [1,3,7]:
            start=datetime.date(2016,5,31)-datetime.timedelta(days=n-1);r=c.execute("SELECT COUNT(DISTINCT OrderID),COUNT(*),SUM(UnpickedUnits) FROM analytics.order_lines WHERE ScenarioID='base' AND UnpickedUnits>0 AND OrderDate>=? AND OrderDate<DATE '2016-06-01'",[start]).fetchone();windows.append([n,start,'2016-05-31',*r,totals[0],totals[1],decimal.Decimal(r[0])/totals[0],decimal.Decimal(r[2] or 0)/totals[1]])
        csvwrite(package/'evidence/cutoff/final_windows.csv',['calendar_days','start_inclusive','end_inclusive','orders','lines','units','all_unpicked_orders_denominator','all_unpicked_units_denominator','order_share','unit_share'],windows)
        # Independent graph traversal from raw rows, not a recursive join that can multiply paths.
        orders=c.execute('SELECT OrderID,BackorderOrderID,OrderDate FROM raw.Sales_Orders ORDER BY OrderID').fetchall();byid={r[0]:r for r in orders};targets={r[1] for r in orders if r[1] is not None};chains=[];cycles=[];date_errors=[]
        for oid,target,dt in orders:
            if target is None:continue
            path=[oid];seen={oid};current=oid
            while byid[current][1] is not None:
                nxt=byid[current][1]
                if nxt not in byid:raise ValueError('Orphaned backorder target')
                if byid[nxt][2]<byid[current][2]:date_errors.append([current,nxt])
                if nxt in seen:cycles.append(path+[nxt]);break
                path.append(nxt);seen.add(nxt);current=nxt
            chains.append([oid,len(path)-1,current,oid in targets,'>'.join(map(str,path))])
        csvwrite(package/'evidence/cutoff/backorder_chains.csv',['original_id','depth','last_target_id','also_target','path'],chains)
        save(package/'evidence/cutoff/chain_summary.json',{'links':len(chains),'distinct_targets':len(targets),'max_depth':max(x[1] for x in chains),'cycles':cycles,'date_sequence_errors':date_errors,'direction':'original references next backorder; description conflict recorded','chain_root': 'original_id can also be intermediate; also_target distinguishes roots'})
        export('backorder_cohort',"""SELECT o.OrderID,o.OrderDate,l.OrderLineID,l.StockItemID,l.UnpickedUnits,orig.OrderID ReferencingOriginalID,orig.OrderDate OriginalDate FROM analytics.orders o JOIN analytics.order_lines l ON l.OrderID=o.OrderID AND l.ScenarioID=o.ScenarioID LEFT JOIN raw.Sales_Orders orig ON orig.BackorderOrderID=o.OrderID WHERE o.ScenarioID='base' AND l.UnpickedUnits>0 ORDER BY o.OrderID,l.OrderLineID,orig.OrderID""")
        # No causal assertion from end windows. A simple SVG is an exportable data figure.
        may=[r for r in daily if str(r[0])[:7]=='2016-05'];v=[int(r[5]) for r in may];maxv=max(v) or 1;pts=' '.join(f'{50+i*26:.1f},{240-x/maxv*190:.1f}' for i,x in enumerate(v));svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="920" height="300"><rect width="100%" height="100%" fill="white"/><text x="50" y="25" font-family="Arial" font-size="18">Stored unpicked units by May order-creation date</text><path d="M50 45 V240 H850" stroke="#666" fill="none"/><polyline points="{pts}" stroke="#176087" stroke-width="3" fill="none"/><text x="50" y="275" font-family="Arial">1 May 2016</text><text x="750" y="275" font-family="Arial">31 May</text><text x="5" y="50" font-family="Arial">{maxv}</text><text x="20" y="240" font-family="Arial">0</text></svg>'
        (package/'reports/daily_may.svg').write_text(svg,encoding='utf-8')
        save(package/'evidence/p1_investigation.json',{'status':'pass-descriptive','seconds':time.perf_counter()-started,'window_results':windows,'cutoff_verdict':'See final-window shares; concentration is descriptive evidence, not causal proof. Full-history target concentration determines story.','operational_failure':'unsupported','display_boundary':'2016-05-31 end-of-calendar-day; age uses date difference only'})
    elif stage=='p2':
        gate=load(package/'evidence/parity.json')
        if gate.get('status')!='pass':raise ValueError('P1 parity gate not accepted')
        export('revenue_reconciliation',"""SELECT i.IsCreditNote,sign(l.ExtendedPrice) AmountSign,COUNT(*) Lines,SUM(CAST(l.Quantity AS DECIMAL(38,2))*l.UnitPrice) ExTaxAmount,SUM(l.TaxAmount) TaxAmount,SUM(l.ExtendedPrice) ExtendedAmount,SUM(l.LineProfit) RecordedLineProfit,SUM(l.ExtendedPrice-(l.Quantity*l.UnitPrice+l.TaxAmount)) ReconciliationDifference,COUNT(*) FILTER(WHERE l.ExtendedPrice<>(l.Quantity*l.UnitPrice+l.TaxAmount)) Exceptions,COUNT(*) FILTER(WHERE l.TaxAmount<>ROUND(l.Quantity*l.UnitPrice*l.TaxRate*CAST(0.01 AS DECIMAL(3,2)),2)) TaxRoundingExceptions FROM raw.Sales_Invoices i JOIN raw.Sales_InvoiceLines l USING(InvoiceID) GROUP BY 1,2 ORDER BY 1,2""",folder='candidates')
        export('revenue_exceptions',"""SELECT l.InvoiceLineID,l.InvoiceID,i.IsCreditNote,l.Quantity,l.UnitPrice,l.TaxRate,l.TaxAmount,l.ExtendedPrice,l.LineProfit,l.ExtendedPrice-(l.Quantity*l.UnitPrice+l.TaxAmount) Difference FROM raw.Sales_InvoiceLines l JOIN raw.Sales_Invoices i USING(InvoiceID) WHERE l.ExtendedPrice<>(l.Quantity*l.UnitPrice+l.TaxAmount) OR l.TaxAmount<>ROUND(l.Quantity*l.UnitPrice*l.TaxRate*CAST(0.01 AS DECIMAL(3,2)),2) ORDER BY l.InvoiceLineID""",folder='candidates')
        export('ordered_value_fallback',"SELECT strftime(OrderDate,'%Y-%m') AS Month,SUM(CAST(l.Quantity AS DECIMAL(38,2))*l.UnitPrice) OrderedValue FROM raw.Sales_Orders o JOIN raw.Sales_OrderLines l USING(OrderID) GROUP BY 1 ORDER BY 1",folder='candidates')
        export('segment_distribution',"""SELECT c.CustomerCategoryID,cat.CustomerCategoryName,COUNT(*) Customers FROM raw.Sales_Customers c LEFT JOIN raw.Sales_CustomerCategories cat USING(CustomerCategoryID) GROUP BY 1,2 ORDER BY 1""",folder='candidates')
        export('segment_orders',"""SELECT COALESCE(cat.CustomerCategoryName,'unknown') CurrentSoldToCategory,COUNT(*) Orders FROM raw.Sales_Orders o LEFT JOIN raw.Sales_Customers c USING(CustomerID) LEFT JOIN raw.Sales_CustomerCategories cat USING(CustomerCategoryID) GROUP BY 1 ORDER BY 1""",folder='candidates')
        export('segment_invoiced_amount',"""SELECT COALESCE(cat.CustomerCategoryName,'unknown') CurrentSoldToCategory,COUNT(*) Lines,SUM(l.ExtendedPrice-l.TaxAmount) ExTaxAmount FROM raw.Sales_Invoices i JOIN raw.Sales_InvoiceLines l USING(InvoiceID) LEFT JOIN raw.Sales_Customers c ON c.CustomerID=i.CustomerID LEFT JOIN raw.Sales_CustomerCategories cat USING(CustomerCategoryID) GROUP BY 1 ORDER BY 1""",folder='candidates')
        export('buying_groups',"""SELECT COALESCE(g.BuyingGroupName,'no buying group') CurrentGroup,COUNT(*) Orders FROM raw.Sales_Orders o JOIN raw.Sales_Customers c USING(CustomerID) LEFT JOIN raw.Sales_BuyingGroups g USING(BuyingGroupID) GROUP BY 1 ORDER BY 1""",folder='candidates')
        export('invoice_order_mapping',"""SELECT COUNT(*) Invoices,COUNT(*) FILTER(WHERE OrderID IS NULL) NullOrderIDs,COUNT(*) FILTER(WHERE OrderID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM raw.Sales_Orders o WHERE o.OrderID=i.OrderID)) OrphanOrderIDs FROM raw.Sales_Invoices i""",folder='candidates')
        export('completion_duration',"""SELECT strftime(OrderDate,'%Y-%m') AS Month,COUNT(*) FILTER(WHERE PickingCompletedWhen IS NOT NULL) Completed,COUNT(*) FILTER(WHERE PickingCompletedWhen IS NULL) Incomplete,COUNT(*) FILTER(WHERE PickingCompletedWhen<CAST(OrderDate AS TIMESTAMP)) Invalid,median(epoch(PickingCompletedWhen-CAST(OrderDate AS TIMESTAMP))/3600) MedianDateBasedHours FROM raw.Sales_Orders GROUP BY 1 ORDER BY 1""",folder='candidates')
        save(package/'evidence/p2_money.json',{'status':'arithmetic-reviewed-currency-pending','seconds':time.perf_counter()-started,'date_basis':'invoice_date','customer_attribution':'current sold-to classification','money_investigation_cap_minutes':60,'currency':'not yet independently verified; do not publish currency-bearing metric until provenance is confirmed','credits':'stored signs preserved; no double negation'})
    elif stage=='p3':
        if not investigation:raise ValueError('P3 requires --investigation history or lateness')
        if load(package/'manifest.json').get('p2_status')!='pass':raise ValueError('P2 acceptance required before optional P3')
        if investigation=='history':
            rows=[]
            for dt in ['2016-04-01','2016-05-01','2016-06-01']:
                n=c.execute("SELECT COUNT(*) FROM raw.Sales_OrderLines l JOIN raw.Sales_Orders o USING(OrderID) WHERE o.OrderDate<? AND (l.PickingCompletedWhen IS NULL OR l.PickingCompletedWhen>=?)",[dt,dt]).fetchone()[0];rows.append([dt,n])
            csvwrite(package/'evidence/candidates/estimated_open_lines.csv',['boundary_exclusive','estimated_lines'],rows)
            save(package/'evidence/candidates/history_verdict.json',{'status':'blocked-exact-history','approximation':'date-only order creation and final completion/current line existence; moved backorder lines and amendments/cancellations not reconstructed','final_boundary_estimate':rows[-1][1],'exact_remaining_units':'blocked: timestamped quantity-change history missing','exact_inventory':'blocked: opening balance and signed movement completeness not certified','budget_minutes':120,'elapsed_seconds':time.perf_counter()-started})
        else:
            export('supplier_lateness',"""SELECT strftime(p.OrderDate,'%Y-%m') AS Month,COUNT(*) EligibleLines,COUNT(*) FILTER(WHERE l.LastReceiptDate>p.ExpectedDeliveryDate) LateLines FROM raw.Purchasing_PurchaseOrders p JOIN raw.Purchasing_PurchaseOrderLines l USING(PurchaseOrderID) WHERE l.IsOrderLineFinalized AND l.ReceivedOuters=l.OrderedOuters AND l.LastReceiptDate IS NOT NULL AND p.ExpectedDeliveryDate IS NOT NULL GROUP BY 1 ORDER BY 1""",folder='candidates')
            export('customer_lateness',"""SELECT strftime(i.InvoiceDate,'%Y-%m') AS Month,COUNT(*) ConfirmedInvoices,COUNT(*) FILTER(WHERE CAST(i.ConfirmedDeliveryTime AS DATE)>o.ExpectedDeliveryDate) LaterCalendarConfirmations FROM raw.Sales_Invoices i JOIN raw.Sales_Orders o USING(OrderID) WHERE i.ConfirmedDeliveryTime IS NOT NULL GROUP BY 1 ORDER BY 1""",folder='candidates')
            save(package/'evidence/candidates/lateness_verdict.json',{'status':'candidate-not-dashboard','supplier_scope':'eligible fully received finalized lines; last receipt versus stored PO expected calendar date; promise history absent','customer_scope':'confirmed invoice grain vs stored order expected calendar date; missing confirmations excluded and reported in core report','budget_minutes':120,'elapsed_seconds':time.perf_counter()-started,'causal_performance':'not established'})
    c.close();print('Investigated',stage,investigation or '',flush=True)
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--package',required=True);p.add_argument('--stage',required=True,choices=['p1','p2','p3']);p.add_argument('--investigation',choices=['history','lateness']);a=p.parse_args();run(a.package,a.stage,a.investigation)


